@js:
云音乐 = cache.getFile('云音乐');
if(云音乐==null){
java.toast('正在获取发现')
Time = 1296e3;//(15天)

ajaxUrl = 'http://121.4.78.106:4001/playlist/catlist'

function getTitle(title,style){
		if(style==0){
				title = '༺ˇ»`ʚ'+title+'ɞ´«ˇ༻'
			}
		else if(style==1){
				title = '༺ '+title+' ༻'
			}
		else{
				title = title
			}
		return '{"title":"'+title+'","url":"","style":{"layout_flexBasisPercent":1}},'
	}


function getSort(title,url){
		return '{"title":"'+title+'","url":"'+url+'","style":{"layout_flexGrow":1}},'
	}



云音乐=getTitle('推荐歌单',0)+getSort('歌曲排行榜','/toplist')+getSort('推荐歌单','/personalized')+getSort('自定义歌单','https://www.baidu.com/')+getTitle(' ',2)+getTitle('歌单分类',0)

$=JSON.parse(java.ajax(ajaxUrl)).sub
title=["语种","风格","场景","情感","主题"]
for(i in title){
	云音乐 += getTitle(title[i],1)
		$.map($=>{
			if($.category==i){
				云音乐 += getSort($.name,'/top/playlist?offset={{(page-1)*50}\}&cat='+$.name)
				}
			});
	}

cache.putFile('云音乐', 云音乐, Time);
java.toast('获取成功，默认保存15天')
}

